/**
 * Hand-written editorial for the provider review pages.
 *
 * WHY THIS FILE EXISTS
 * The Sep 2026 content brief (§4) names 11 /companies/* pages at 30-60%
 * duplicate and asks for unique blocks on each. src/lib/provider-profile.ts
 * already made the argument against solving that with more generation, in its
 * own header: "More skeletons filled from the same fields is the same
 * scaled-content signal in a different costume." Measured on the build it was
 * right — rewriting the /compare/* blurbs to cite each pair's own numbers moved
 * one page from 87.5% to 88.9% duplicate, because sentence frames collide even
 * when every figure inside them differs. So these are written one at a time.
 *
 * WHAT WE CAN SAY THAT COMPETITORS CANNOT
 * Monito, Exiap, NerdWallet and the rest publish a point-in-time quote and an
 * editorial opinion. We hold 125,676 provider-day observations across 216
 * comparable corridors over a 91-day window, which supports three claims none
 * of them can make:
 *
 *   1. How often a provider actually LED its corridors, with the denominator —
 *      not "cheap", but 41 of 153.
 *   2. How far behind it sits when it does not lead (average shortfall), which
 *      separates "rarely first but always close" from "rarely first and far
 *      back" — the difference between Revolut and PayPal.
 *   3. What a provider costs at $100 versus $1,000. This is the finding most
 *      worth publishing: Wise costs 7.77% on $100 against 1.75% on $1,000, a
 *      6.02pp penalty and the worst of any provider we price, while InstaReM is
 *      cheaper on the small transfer than the large one. Every competitor
 *      review recommends Wise flatly; none of them tells a reader sending $100
 *      that it is the wrong tool.
 *
 * WHY THE FIGURES ARE TOKENS
 * CLAUDE.md: never hand-type a figure a dataset already knows. Figures below are
 * {{TOKEN}}s resolved at render against the same indices the rest of the site
 * publishes, so the prose cannot drift from the data. A provider we do not
 * measure gets no measured claim at all — check:rankings fails a silent one.
 */

export interface CompanyEditorialSection {
  heading: string;
  /** May contain {{TOKEN}}s and inline <a>/<strong>/<em>. */
  body: string;
}

export interface CompanyEditorial {
  /** What this provider actually is, and the decision it belongs in. */
  theVerdict: string;
  /** Our longitudinal record for it, stated with denominators. */
  measuredRecord: string;
  /** Where it genuinely wins. */
  whereItWins: CompanyEditorialSection;
  /** Where it is the wrong tool — named plainly. */
  whereItLoses: CompanyEditorialSection;
  /** The specific thing a reader should check before committing. */
  watchOut: string;
  /**
   * Named corridors this provider actually led over the 91-day window, via
   * {{LEAD_PAIRS}}. Optional — thin for providers that rarely lead. Genuinely
   * new information, not padding: naming routes is the differentiator no
   * competitor review makes (see the competitor research this file's header
   * describes — Monito names continents, never corridors).
   */
  namedCorridors?: string;
}

export const companyEditorial: Record<string, CompanyEditorial> = {
  "ria": {"theVerdict": "For a Ria cash transfer, the key decision is whether the intended recipient can collect at the location selected in the sending flow. A network total cannot answer that question. Price the actual pickup arrangement, then compare it with a bank deposit if the recipient can use one.", "measuredRecord": "The rates shown on this page are the offers available in our comparison data. They do not verify the cash stock, hours or identity checks of an individual Ria agent. Keep the selected receiving location with the quote when comparing alternatives.", "whereItWins": {"heading": "When a Ria pickup fits the payment", "body": "A recipient who needs physical currency may prefer a confirmed local pickup to an account credit followed by a separate withdrawal. Agree the collection point before sending, particularly when the recipient would need transport to reach it."}, "whereItLoses": {"heading": "When collection creates an extra obstacle", "body": "An inaccessible counter, a mismatch in the recipient name or unavailable identification can make an otherwise attractive quote unusable. In that case, check a supported account payout rather than assuming another nearby shop can pay the same transfer."}, "watchOut": "Ria\u2019s <a href=\"https://help.riamoneytransfer.com/hc/en-us/articles/4406058323601-What-does-my-recipient-need-to-pickup-a-cash-money-transfer\" target=\"_blank\" rel=\"noopener noreferrer\">collection instructions</a> require the transfer PIN and current government-issued photo identification in the recipient\u2019s name. Share the PIN privately with the recipient and keep it out of public messages."},
  "sendwave": {"theVerdict": "Sendwave should be evaluated on the receiving method offered for your particular destination. A mobile-money transfer, a bank deposit and a Sendwave Wallet transfer are different products; a previous successful payment through one does not establish the terms of another.", "measuredRecord": "Use the displayed comparison as a price check for its stated currency pair and amount. Sendwave\u2019s final confirmation remains the place to check the fee, exchange rate and receiving method for your actual beneficiary. Promotional pricing or wallet rewards should not be assumed to apply to every transfer.", "whereItWins": {"heading": "A repeat payment to a confirmed recipient", "body": "Saving a beneficiary can simplify an allowance when the same account or mobile-money number remains active. Before repeating it, check that the selected receiving product still matches the one the family expects."}, "whereItLoses": {"heading": "When the destination product is unclear", "body": "Do not treat a balance in Sendwave Wallet as identical to a local-currency bank credit. If a further conversion or withdrawal is needed for the recipient\u2019s bill, include that step before comparing usable payouts."}, "watchOut": "Sendwave\u2019s <a href=\"https://www.sendwave.com/en/support\" target=\"_blank\" rel=\"noopener noreferrer\">support information</a> says pricing depends on the route, funding, receiving method and amount. It publishes delivery ranges rather than a universal instant-arrival promise. Check the estimate shown for the selected payment before confirming."},

  wise: {
    theVerdict: `Wise is the default recommendation of almost every comparison site, and on the evidence we hold that is mostly deserved — but the recommendation is usually made without a condition attached, and it needs one. Wise publishes the mid-market rate and charges a visible fee instead of burying its margin in the rate, which is why it is the usual leader on {{LED:wise}} corridors where we can compare it. That same fee structure is what makes it the wrong tool for a small transfer: the fee does not shrink with the amount, so it eats a much larger share of $100 than of $1,000. Wise is a bank-to-bank service with no cash payout at all, so it is also not an option when the recipient cannot receive a deposit.`,
    measuredRecord: `Over the last 91 days Wise was the most frequent winner on {{LED:wise}} corridors where we could compare it — {{LEADRATE:wise}} of them — and it won {{WINRATE:wise}} of the contested days it quoted; when it was not first it trailed the leader by {{SHORTFALL:wise}} on average. Across {{COSTCORRIDORS:wise}} corridors its average all-in cost at $1,000 was {{AVGCOST:wise}}. Now the part that is usually left out: at $100 that figure is {{SMALLCOST:wise}} against {{BIGCOST:wise}} at $1,000, a penalty of {{SMALLPENALTY:wise}} — the largest gap between small and large transfers of any provider we price. Wise can be a sound choice at $1,000 and one of the most expensive at $100. Both statements come from the same dataset.`,
    whereItWins: {
      heading: "Best for bank-to-bank transfers of $1,000 and up",
      body: `If the recipient has an account and the amount is meaningful, Wise is the strongest evidence-backed choice on this site. The 0% markup means its cost does not scale with the transfer the way a percentage markup does, so the advantage widens as the amount grows — which is why it suits tuition, rent, payroll, contractor invoices and moving money between your own accounts abroad. It supports transfers to $1,000,000, holds balances in 50 currencies, and is regulated by the FCA, FinCEN and ASIC. The rate it gives you is one you can check against any published mid-market quote, which is not true of a provider that marks the rate up.`,
    },
    whereItLoses: {
      heading: "Avoid for small amounts and any cash payout",
      body: `At $100 Wise cost {{SMALLCOST:wise}} on our measurements — worse than most specialist remittance apps, several of which charge roughly the same in percentage terms at $100 as at $1,000. If you are sending small amounts regularly, this is the single most expensive habit on this page, and the providers built for that pattern beat it clearly. Wise also has no cash pickup, no mobile money and no home delivery, and reaches 80 countries against 100-200 for the remittance networks. For a recipient without a usable bank account, Wise is not a more expensive option — it is not an option.`,
    },
    watchOut: `Check the amount before you assume the recommendation holds: our figures show the ranking genuinely inverts between $100 and $1,000, so run your own number rather than carrying a general recommendation across. Wise's fee also varies by currency and by how you fund the transfer — a card-funded transfer costs more than one funded from a bank account. Safeguarded funds are not the same thing as FSCS or FDIC deposit insurance; confirm what protection applies to your balance if you intend to hold money rather than send it.`,
    namedCorridors: `The corridors it actually led, by name rather than by count: {{LEAD_PAIRS:wise}}. Naming the routes matters because a percentage tells you nothing about whether YOUR corridor is one of them — check the list, or the live comparison for your currency pair, rather than assuming an overall record carries over.`,
  },

  instarem: {
    theVerdict: `InstaReM is rarely the first name in a comparison, yet it performs well in our data. It is a Singapore-headquartered transfer service, part of the Nium group, running bank-to-bank payouts across Asia-Pacific, Europe and North America. It has no cash pickup network and no retail brand to speak of, which is most of why it is less known than the brands above it in most rankings. On the corridors where we can price it, it is the usual leader on {{LEADRATE:instarem}} of them, and at $100 its all-in cost was {{SMALLCOST:instarem}}.`,
    measuredRecord: `Over the last 91 days InstaReM was the most frequent winner on {{LED:instarem}} comparable corridors — {{LEADRATE:instarem}} of them, against {{LEADRATE:wise}} for Wise — and when it lost it trailed the leader by {{SHORTFALL:instarem}} on average. Average all-in cost at $1,000 across {{COSTCORRIDORS:instarem}} corridors was {{AVGCOST:instarem}}. The striking figure is the small-transfer one: {{SMALLCOST:instarem}} at $100 against {{BIGCOST:instarem}} at $1,000, a difference of {{SMALLPENALTY:instarem}}. For comparison, Wise costs {{SMALLCOST:wise}} on the same $100.`,
    whereItWins: {
      heading: "InstaReM on small transfers",
      body: `If you send $100-200 regularly — the pattern most remittance senders actually follow — InstaReM cost {{SMALLCOST:instarem}} all-in at $100 against {{BIGCOST:instarem}} at $1,000, so sending less does not cost it a meaningfully higher percentage. It combines that with a lead rate of {{LEADRATE:instarem}} against Wise's {{LEADRATE:wise}} and an average shortfall of {{SHORTFALL:instarem}} on the corridors where it is not first. It is regulated across multiple jurisdictions including MAS in Singapore, and pays out to bank accounts across roughly 55 currencies.`,
    },
    whereItLoses: {
      heading: "No cash, no wallet, and a narrower corridor list",
      body: `InstaReM pays out to bank accounts only. There is no cash pickup, no mobile money and no home delivery, so for a recipient collecting cash it is not usable at any price. We could price it on {{COSTCORRIDORS:instarem}} corridors against {{COSTCORRIDORS:taptap-send}} for TapTap Send and {{COSTCORRIDORS:wise}} for Wise, so its coverage is narrower than the leaders — on an unusual corridor it may simply not quote. Its consumer brand recognition is low, which matters only insofar as a recipient may not recognise the sender's name on an incoming payment.`,
    },
    watchOut: `Confirm InstaReM serves your specific corridor and payout method before planning around it — our quotes are collected by currency pair rather than by sending country, so a good price on your currency pair does not confirm it accepts senders in your country. First-transfer promotional rates are excluded from our figures but may change what you pay once; compare the returning-customer price if you intend to send regularly.`,
  },

  "taptap-send": {
    theVerdict: `TapTap Send is a mobile-first remittance app aimed squarely at diaspora senders moving money to Africa, Asia and Latin America, with bank, mobile wallet and cash payout depending on the destination. It is also a paid partner of this site, which is why the claim below is a measured record with its denominator rather than an adjective — it appears in our rankings in the position the data puts it, and a commercial relationship does not move it. On the evidence, it is one of the two most consistent leaders we track, and it holds the widest corridor coverage in our cost index.`,
    measuredRecord: `Over the last 91 days TapTap Send was the most frequent winner on {{LED:taptap-send}} comparable corridors — {{LEADRATE:taptap-send}} of them, against {{LED:wise}} ({{LEADRATE:wise}}) for Wise — and it did that across a far larger corridor set than most of the field. When it did not lead it trailed by {{SHORTFALL:taptap-send}} on average, one of the smallest average shortfalls we measure. Average all-in cost at $1,000 was {{AVGCOST:taptap-send}} across {{COSTCORRIDORS:taptap-send}} corridors, the widest coverage in our cost index. It is also close to flat across transfer sizes: {{SMALLCOST:taptap-send}} at $100 against {{BIGCOST:taptap-send}} at $1,000, a difference of {{SMALLPENALTY:taptap-send}} — where Wise's equivalent gap is {{SMALLPENALTY:wise}}.`,
    whereItWins: {
      heading: "Small, frequent transfers to Africa, Asia and Latin America",
      body: `TapTap Send is built for the sender moving modest amounts home on a regular schedule, and the measurements fit that design: a flat cost curve between $100 and $1,000, no transfer fee on the corridors we price, and an average shortfall of {{SHORTFALL:taptap-send}} behind the best payout on the days it is not first. Payout to mobile wallets and cash makes it usable where a bank-only service is not, and delivery on most corridors is quoted in minutes.`,
    },
    whereItLoses: {
      heading: "Not a general-purpose or large-transfer service",
      body: `Its whole cost advantage sits in the rate rather than a fee, so on corridors where a bank-rail specialist like Wise or InstaReM prices tightly it can be beaten, particularly at larger amounts where a 0% markup compounds in the other direction. It is a consumer remittance app rather than a business or high-value FX service: there is no multi-currency account, no forward contract, no dealer, and it is not the tool for a property purchase or a commercial payment. Coverage is destination-led — strong where the diaspora corridors are, thin elsewhere.`,
    },
    watchOut: `TapTap Send is a paid partner of SendMoneyCompare. That relationship pays for a highlighted placement; it does not change its position in any ranked table on this site, which is ordered by what the recipient receives. Treat the figures above as what we measured, and check a live quote for your own corridor, amount and payout method before sending — availability and final rates depend on your transfer.`,
    namedCorridors: `The corridors where it was the usual leader over the 91-day window: {{LEAD_PAIRS:taptap-send}}. That is the concrete version of the record above — not an adjective, a route list you can check your own corridor against.`,
  },

  xe: {
    theVerdict: `XE is best known for its currency data — the rate pages and the converter — and the transfer service sits alongside that brand. It is a long-established, heavily regulated bank-to-bank service with a very wide published currency list, owned by Euronet. Our measurements show a pattern worth understanding before you use it, because it is the clearest example on the site of why a low average cost and a good deal are not the same claim: XE looks inexpensive on the corridors where it quotes, and almost never actually wins one.`,
    measuredRecord: `Over the last 91 days XE was the most frequent winner on {{LED:xe}} comparable corridors, and it won {{WINRATE:xe}} of the contested days it quoted — effectively never first — and when it lost it trailed the leader by {{SHORTFALL:xe}} on average. Its average all-in cost at $1,000 was {{AVGCOST:xe}}, which reads as the lowest on this page until you see the denominator: that average is taken over just {{COSTCORRIDORS:xe}} corridors, against {{COSTCORRIDORS:wise}} for Wise and {{COSTCORRIDORS:taptap-send}} for TapTap Send. A low average over a small, self-selected corridor set is not comparable to a low average over a large one. On small transfers it costs {{SMALLCOST:xe}} against {{BIGCOST:xe}} at $1,000, a {{SMALLPENALTY:xe}} penalty.`,
    whereItWins: {
      heading: "Unusual currencies and larger, planned transfers",
      body: `XE's published currency list is one of the widest available, which is the practical reason to use it: if you are sending to a destination the remittance apps do not serve, it may quote where they do not. It charges no transfer fee, supports transfers up to $500,000, and carries an unusually broad regulatory footprint — FCA, FinCEN, ASIC and FINTRAC. Like other broker-model services its rates improve as the amount rises, so its natural case is a larger, planned, bank-to-bank transfer rather than a small urgent one.`,
    },
    whereItLoses: {
      heading: "Rarely the cheapest on a contested corridor",
      body: `On the corridors where several providers compete, XE was the usual leader on {{LED:xe}} in 91 days. If your corridor is well served, you are very likely to find a better payout elsewhere, and on average you are giving up {{SHORTFALL:xe}} to do so. There is no cash pickup, no mobile money and no spending account — it is bank deposit only — and settlement is quoted in business days rather than minutes, so it is the wrong instrument for anything urgent.`,
    },
    watchOut: `Read XE's "no transfer fees" as a description of the fee line, not of the cost: our figures are all-in, combining fee and exchange-rate markup, and the markup is where this service is priced. Because we could compare XE on relatively few corridors, treat its average cost as indicative rather than as a like-for-like ranking against providers measured across hundreds. Get a quote for your own corridor and amount.`,
  },

  ofx: {
    theVerdict: `OFX is a broker-model FX service: no transfer fee, bank-to-bank only, no upper transfer limit, and a dealer you can speak to once the amount is large. That model is aimed at a specific customer — someone moving a substantial sum on a planned timetable, such as a property purchase, an emigration or a business payment — and it is a reasonable fit for that. It is a poor fit for ordinary remittance-sized transfers, and our cost measurements say so plainly, which is the opposite of how a fee-free service is usually presented.`,
    measuredRecord: `Across {{COSTCORRIDORS:ofx}} corridors, OFX's average all-in cost at $1,000 was {{AVGCOST:ofx}} — the highest of any provider covered on this page, despite charging no transfer fee at all. That cost sits entirely in the exchange rate. A caveat on the win data, because the sample does not support a strong claim: we could compare OFX head-to-head on only a handful of corridors, and it was the usual leader on {{LED:ofx}} of them, winning {{WINRATE:ofx}} of the contested days it quoted. A sample that small cannot be set beside Wise's record across {{LED:wise}} corridors; average shortfall, at {{SHORTFALL:ofx}}, is the fairer read.`,
    whereItWins: {
      heading: "Large, planned transfers with dealer support",
      body: `There is no upper limit and no transfer fee, and above roughly $10,000 OFX assigns a dealer you can call — genuinely useful when a transfer is time-sensitive, needs splitting across dates, or forms part of a property or emigration transaction where a fractional rate improvement outweighs everything else. Its published reach is among the widest here at around 190 countries, and it is regulated by ASIC, the FCA and FinCEN. Broker rates improve with size, so the figures above, measured at $1,000, understate how it performs at the amounts it is built for.`,
    },
    whereItLoses: {
      heading: "The most expensive option we measured at $1,000",
      body: `At the amount most people actually send, OFX was the costliest provider on this page on our measurements, at {{AVGCOST:ofx}} all-in. "No transfer fees" is accurate and, read as a statement about total cost, misleading — the margin is in the rate. It pays out to bank accounts only, with no cash pickup or mobile money, and settles in one to three business days rather than minutes. For a small or urgent transfer, this is the wrong instrument on both counts.`,
    },
    watchOut: `"No transfer fee" is a US-specific policy — OFX's own site states US transfers are fee-free regardless of amount. Outside the US, it isn't unconditional: Australia and Canada both charge a flat AU$/CA$15 below a AU$/CA$10,000 transfer, waived above it, and other countries set their own threshold. Check the policy for your own country before assuming the US figure applies. Separately, our cost figures are measured at $1,000 and OFX's proposition is quoted rates that improve with transfer size, so do not carry the number above to a $50,000 transfer — request a quote at your actual amount, and ask explicitly what rate you are being given against the mid-market rate on the day. We also could not compare OFX on enough corridors to publish a small-transfer figure, so no claim is made here about what it costs at $100.`,
  },
  remitly: {
    theVerdict: `Remitly is a remittance app rather than a general transfer service, and the distinction explains almost everything about how it performs in our data. It is built for the recurring sender supporting family abroad, with cash pickup, mobile money and home delivery across roughly 100 countries, and it competes on reach, speed and reliability rather than on being the cheapest payout. It carries one of the highest Trustpilot scores of any provider we list while leading very few corridors on price — a combination that is easy to misread. Customers are rating whether the money arrived, to the right person, on time. They are not rating the exchange rate.`,
    measuredRecord: `Over the last 91 days Remitly was the most frequent winner on {{LED:remitly}} comparable corridors ({{LEADRATE:remitly}}), and when it was not first it trailed the leader by {{SHORTFALL:remitly}} on average. The corridors it did lead were {{LEAD_PAIRS:remitly}}. Its average all-in cost at $1,000 was {{AVGCOST:remitly}} across {{COSTCORRIDORS:remitly}} corridors; at $100 it was {{SMALLCOST:remitly}}, a {{SMALLPENALTY:remitly}} penalty — moderate, and well below Wise's {{SMALLPENALTY:wise}}. Read those together: Remitly is usually not the cheapest payout, but it is not badly placed either, and it holds up better than most on the small transfers its customers actually send.`,
    whereItWins: {
      heading: "Recurring remittances where the payout method matters",
      body: `Remitly is the stronger choice when the recipient's collection method decides the transfer: cash pickup, mobile money or home delivery, none of which bank-rail services like Wise or InstaReM offer at any price. Express delivery arrives in minutes; economy costs less when the money can wait, and choosing between them is a real lever most providers do not give you. Its Trustpilot standing is among the best we track, which for a service people use monthly to support family is not a trivial consideration.`,
    },
    whereItLoses: {
      heading: "Rarely the cheapest payout on a contested corridor",
      body: `On the corridors where several providers compete, Remitly was the usual leader on {{LED:remitly}} in 91 days. If your recipient can take a bank deposit and you are optimising on cost, you will usually find a better payout elsewhere — on average {{SHORTFALL:remitly}} better. Remitly publishes a $300,000 ceiling on transfers from the US, though an individual account's limit may be lower and depends on verification level, payment method and destination; coverage is 100 countries and roughly 40 currencies, narrower than the legacy cash networks. Its promotional first-transfer rates are excluded from our figures deliberately, because they apply once and the ongoing price applies every month after.`,
    },
    watchOut: `Compare the returning-customer price, not the welcome offer. For a realistic annual cost, price the first transfer plus eleven repeats at the same amount rather than treating an introductory rate as your ongoing cost — this is the single most common way a remittance app looks cheaper than it is. Also confirm the arrival estimate for your actual payment and payout method: an express quote assumes funding and verification are already done.`,
    namedCorridors: `The corridors it led over the 91-day window: {{LEAD_PAIRS:remitly}}. Check them against the diaspora routes (South Asia, the Philippines, East Africa) Remitly's own marketing leans on before assuming its lead corridors match its brand positioning.`,
  },

  worldremit: {
    theVerdict: `WorldRemit is a digital remittance service built around the last mile in emerging markets: mobile money wallets, cash pickup and airtime top-up alongside bank deposit, across roughly 130 countries and one of the widest currency lists in the category. It runs no agent network of its own, so it is cheaper to operate than the legacy cash providers and prices accordingly. In our data it sits in a consistent middle position — rarely the cheapest, rarely far off — and its real argument is what it can do rather than what it costs.`,
    measuredRecord: `Over the last 91 days WorldRemit was the most frequent winner on {{LED:worldremit}} comparable corridors ({{LEADRATE:worldremit}}), specifically on {{LEAD_PAIRS:worldremit}}. When it was not first it trailed by {{SHORTFALL:worldremit}} on average, which is tighter than most of the cash-capable field. Average all-in cost at $1,000 was {{AVGCOST:worldremit}} across {{COSTCORRIDORS:worldremit}} corridors. Its small-transfer behaviour is one of its better features: {{SMALLCOST:worldremit}} at $100 against {{BIGCOST:worldremit}} at $1,000, a {{SMALLPENALTY:worldremit}} penalty — one of the flatter cost curves we measure, and a fifth of Wise's {{SMALLPENALTY:wise}}.`,
    whereItWins: {
      heading: "Mobile money, cash and airtime in emerging markets",
      body: `Mobile money into wallets such as M-Pesa and MTN, and airtime top-up direct to a recipient's phone, are payout methods most competitors do not offer at all — and across much of sub-Saharan Africa and parts of South and Southeast Asia they are how money is normally received. Add cash pickup and bank deposit, roughly 70 currencies, fees from $0.99, and a flat cost curve that does not punish the $100 transfers this audience actually sends. For that sender, the comparison is frequently not close, because the alternatives cannot complete the transfer.`,
    },
    whereItLoses: {
      heading: "Not the cost leader, and not built for large amounts",
      body: `WorldRemit was the usual leader on {{LED:worldremit}} comparable corridors over 91 days, so on a well-served bank corridor you will usually do better elsewhere. Transfers cap at $10,000, which rules out property, tuition instalments and most business payments, and there is no multi-currency account or dealer service. We could price it on {{COSTCORRIDORS:worldremit}} corridors — a narrower set than the leaders — so on an unusual route it may not quote at all.`,
    },
    watchOut: `Mobile money and airtime availability vary by country and by network, and pricing differs by payout method, so a good bank-deposit quote does not tell you what a wallet payout costs. Confirm the recipient's wallet provider is supported before relying on it. Our quotes are collected by currency pair rather than sending country, so check that WorldRemit accepts senders from your country.`,
    namedCorridors: `The corridors it led over the 91-day window: {{LEAD_PAIRS:worldremit}}. That's a short list next to Wise's, which is consistent with WorldRemit's whole proposition — it competes on payout reach rather than being the cheapest, so leading outright on any corridor at all is the exception rather than the rule.`,
  },

  "western-union": {
    theVerdict: `Western Union has been moving money since 1851 and its product is the agent network: roughly 200 countries, 130 currencies, and a staffed counter in places no app reaches. That network is a genuine asset and it is also the thing you are paying for. In our measurements it is the strongest performer among the legacy cash providers and still well behind the digital specialists on cost, which is the honest summary — the premium is real, it is quantifiable, and for a large number of senders it buys the only option that works.`,
    measuredRecord: `Over the last 91 days Western Union was the most frequent winner on {{LED:western-union}} comparable corridors ({{LEADRATE:western-union}}, against {{LEADRATE:moneygram}} for MoneyGram), on {{LEAD_PAIRS:western-union}}. When it was not first it trailed the leader by {{SHORTFALL:western-union}} on average. Its average all-in cost at $1,000 was {{AVGCOST:western-union}} across {{COSTCORRIDORS:western-union}} corridors, against {{AVGCOST:wise}} for Wise and {{AVGCOST:taptap-send}} for TapTap Send. At $100 it cost {{SMALLCOST:western-union}}, a {{SMALLPENALTY:western-union}} penalty — notably flat, so unlike most of the field it does not get disproportionately worse on small amounts.`,
    whereItWins: {
      heading: "Reach, cash, and transfers a digital service cannot complete",
      body: `Around 200 countries, 130 currencies and transfers to $50,000, with bank deposit and mobile wallet alongside cash. For a recipient without a bank account, in a country the apps do not serve, or who needs to walk into a known location and collect cash with identification, this is the service that works. It is also comparatively flat across transfer sizes, so the small-transfer penalty that hits Wise hardest does not apply here.`,
    },
    whereItLoses: {
      heading: "A measurable premium on any corridor with competition",
      body: `Western Union averages {{AVGCOST:western-union}} all-in on the corridors we price, against {{AVGCOST:wise}} for Wise and {{AVGCOST:remitly}} for Remitly, and it was the usual leader on only {{LED:western-union}} comparable corridors. If your recipient can take a bank deposit or a mobile wallet, you are very likely paying for a network you are not using. Pricing also varies sharply by payout method and by how you fund the transfer, so the figure above is an average across conditions rather than a quote.`,
    },
    watchOut: `Western Union prices cash pickup differently from bank deposit, and card-funded transfers cost more than bank-funded ones, so quote your exact combination rather than assuming the average applies. Agent-level pricing is not something we observe. Check the collection location and the identification your recipient will need before sending — a better rate at an agent two hours away is worth nothing.`,
    namedCorridors: `The corridors it led over the 91-day window: {{LEAD_PAIRS:western-union}}. The pattern is specific rather than random — read the sending currency on each pair — and a reminder to check the actual list rather than assume a lead count spreads evenly across the routes you might care about.`,
  },

  moneygram: {
    theVerdict: `MoneyGram is the other incumbent cash network, reaching roughly 200 countries through agent locations in supermarkets, banks and post offices. Our data shows an unusual pattern for it, and it is worth stating plainly because it cuts against the obvious reading: MoneyGram essentially never comes first on price, yet its average cost is materially lower than Western Union's. It is a consistent mid-table provider rather than a cheap one or an expensive one, and the case for using it is almost always locational.`,
    measuredRecord: `Over the last 91 days MoneyGram was the most frequent winner on {{LED:moneygram}} comparable corridors and won {{WINRATE:moneygram}} of the contested days it quoted — effectively never first — while trailing the leader by {{SHORTFALL:moneygram}} on average when it lost. That shortfall is smaller than Western Union's {{SHORTFALL:western-union}}, and its average all-in cost at $1,000, {{AVGCOST:moneygram}} across {{COSTCORRIDORS:moneygram}} corridors, is well below Western Union's {{AVGCOST:western-union}}. So between the two legacy networks, Western Union wins outright more often and MoneyGram is cheaper on average — a genuine split that a simple "who is cheapest" ranking hides. At $100 MoneyGram cost {{SMALLCOST:moneygram}}, a {{SMALLPENALTY:moneygram}} penalty.`,
    whereItWins: {
      heading: "When its agent is the convenient one",
      body: `MoneyGram's argument is where its counters are. Roughly 200 countries, fees from $1.99, bank deposit and mobile wallet alongside cash, and on our figures a lower average cost and a tighter average shortfall than Western Union. If the recipient's nearest reliable collection point is a MoneyGram agent, that settles the question, and the pricing is not a reason to argue with it.`,
    },
    whereItLoses: {
      heading: "Never the cheapest, and capped at $10,000",
      body: `MoneyGram was the usual leader on {{LED:moneygram}} comparable corridors in 91 days. On any corridor with digital competition there is a better payout available, and if the recipient can take a bank deposit you are paying a cash-network premium for nothing. Transfers cap at $10,000, against $50,000 at Western Union, and its currency list is roughly 50 against Western Union's 130.`,
    },
    watchOut: `Fees vary by corridor, payout method and funding method, and agent-level pricing is not something we observe, so the averages above are not a quote. Confirm the collection location, the agent's opening hours and the identification required before you send. If the recipient can receive a bank deposit or a mobile wallet payment, price those options too before defaulting to cash.`,
  },

  xoom: {
    theVerdict: `Xoom is PayPal's remittance service: cash pickup, mobile reload and bank deposit across roughly 130 countries, funded from a PayPal balance, a bank account or a card, and settling in minutes on most routes. Its proposition is speed and the removal of friction for people who already hold a PayPal account — the identity checks are largely done, and funding is immediate. It is priced accordingly, and our coverage of it is thinner than for most providers on this page, which we would rather say than paper over.`,
    measuredRecord: `Over the last 91 days Xoom was the most frequent winner on {{LED:xoom}} comparable corridors ({{LEADRATE:xoom}}), on {{LEAD_PAIRS:xoom}}. When it was not first it trailed by {{SHORTFALL:xoom}} on average, so choosing it by default has a measurable cost. Its average all-in cost at $1,000 was {{AVGCOST:xoom}}, but that figure rests on only {{COSTCORRIDORS:xoom}} corridors, far fewer than the {{COSTCORRIDORS:wise}} behind Wise's, so treat it as indicative rather than as a like-for-like ranking.`,
    whereItWins: {
      heading: "Speed, and an account you already have",
      body: `If the money has to arrive today and the recipient needs cash, Xoom is built for exactly that: minutes to most destinations, cash pickup and mobile reload alongside bank deposit, and transfers to $50,000. For an existing PayPal user the first transfer is dramatically faster to complete than opening a new account with a specialist, which is a real advantage the day you need it rather than a theoretical one.`,
    },
    whereItLoses: {
      heading: "A wide average shortfall and thin measured coverage",
      body: `At {{SHORTFALL:xoom}} average shortfall, Xoom gives up more than most providers when it is not leading, and it was the usual leader on {{LED:xoom}} comparable corridors. If the transfer is not urgent and the recipient can take a bank deposit, the specialists beat it clearly. Our own coverage is a limitation worth weighing: {{COSTCORRIDORS:xoom}} corridors is a thin base, so we are less confident about Xoom than about providers we price across hundreds.`,
    },
    watchOut: `Xoom prices cash pickup differently from bank deposit, and funding from a card costs more than funding from a bank account, so quote your exact combination. Because our measured coverage of Xoom is narrow, treat the figures above as indicative and get a live quote for your corridor and amount before relying on them.`,
    namedCorridors: `The corridors it led: {{LEAD_PAIRS:xoom}}. That is not a pattern worth reading much into given how thin the sample is — {{LED:xoom}} comparable corridors — but it is the whole list, and it tells you where to actually check a live quote rather than assume Xoom performs the same way on a US-originated transfer.`,
  },

  "ace-money-transfer": {
    theVerdict: `ACE Money Transfer is a UK-headquartered remittance service focused on corridors from Europe, the UK and Australia into South Asia, Africa and the Philippines, offering bank deposit, cash pickup and mobile wallet payout. We are going to be straight about the limits of this page: ACE does not appear in any of the pricing datasets behind the rest of this site, so nothing here ranks it on cost, and we make no claim about how it compares. That gap is not unique to us — ACE has no provider review on Monito, MoneyTransfers.com or Exiap either, which is itself worth knowing when you are trying to research it.`,
    measuredRecord: `We hold no measured pricing record for ACE Money Transfer. It is absent from our consistency index, which tracks how often each provider leads its corridors over a rolling 91-day window, and from our remittance cost index, which prices providers across more than a thousand corridors at $1,000. Every other provider reviewed on this site carries a figure in both. Rather than fill the gap with a plausible-sounding estimate, we are stating it: the win rates, average shortfalls and cost percentages quoted elsewhere on this site do not exist for ACE, and any comparison you see between ACE and another provider on those measures — here or anywhere — is not coming from observed quote data.`,
    whereItWins: {
      heading: "Corridors and features it publishes",
      body: `ACE advertises South Asian, African and Philippine corridors from the UK, Europe and Australia, with bank deposit, cash pickup and mobile wallet payout, and its <a href="https://acemoneytransfer.com/company-profile" target="_blank" rel="noopener noreferrer nofollow">company profile</a> names its regulators as the FCA in the UK (reference 506692), the Central Bank of Ireland, AUSTRAC in Australia and FINTRAC in Canada. Its Trustpilot standing is strong. These are the company's own published claims and a third-party review score, not our measurements — we are reporting what it says about itself, clearly labelled as such, because that is the honest version of a review we cannot price.`,
    },
    whereItLoses: {
      heading: "We cannot tell you what it costs",
      body: `The thing a comparison site exists to answer — is this cheaper than the alternative, and by how much — is the thing this page cannot answer for ACE. Our scrapers do not collect its quotes, so it never enters a ranked table on this site, and its absence from those tables reflects missing data rather than poor performance. If you are considering ACE, get a live quote from it and compare the total received against the providers we do price on your corridor.`,
    },
    watchOut: `Treat any cost claim about ACE Money Transfer on this site as absent rather than favourable or unfavourable. The practical check is the same one we would recommend anywhere: request a quote for your exact amount, funding method and payout method, note the total debited and the amount your recipient receives, and compare that against a quote from the providers in our comparison table for the same corridor on the same day.`,
  },
  "natwest": {"theVerdict":"NatWest (National Westminster Bank plc) is a UK bank that sends international payments from a personal current account through the NatWest app, Online Banking or a branch. It suits an existing customer paying a bank account abroad from the account they already use, with NatWest's own controls wrapped around the payment. As of October 2026 its help pages describe payments to an account identified by an IBAN, an account number or a national clearing code, and no cash or wallet payout.","measuredRecord":"We price NatWest in our 91-day record at £100, the one amount our rate history keeps for every provider. On that footing NatWest was the usual leader on {{LED:natwest}} comparable sterling corridors, and its quote averaged {{SHORTFALL:natwest}} behind the day's leading payout. NatWest says it shows the rate and the full cost before you confirm, and that figure is the one to compare for a larger sum.","whereItWins":{"heading":"Repeat payments to a saved payee in the app","body":"Once biometrics are registered, NatWest lets Personal and Premier customers send up to £20,000 a day from the app, and a saved payee needs only selecting before the confirmation screen. The app asks you to choose how charges are split before you pay, and the payment form has a National Clearing Code box, where NatWest wants a Canadian transit number, a US routing number or an Australian BSB entered."},"whereItLoses":{"heading":"A first large payment to a new payee in the app","body":"Without biometrics, NatWest limits app payments to a new payee to £750 a day, spread over at most five payments, and anyone paying a new payee more than £1,000 is sent to Online Banking. Beyond the digital limits it asks for a branch visit with your debit card and ID, and, for more than £20,000 when you cannot reach a branch, a signed form posted or faxed to its payments centre in Manchester."},"watchOut":"Personal customers can freeze international payments in the NatWest app, and its <a href=\"https://www.natwest.com/support-centre/banking-from-home/make-payments/how-can-i-make-an-international-payment.html\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">international payment guide</a> says that control must be unfrozen before an app or Online Banking payment will go through. Check destination rules as well: NatWest wants a 26-digit IBAN and a payment reason on every payment to Turkey, a purpose of payment code on every payment to India, and pays France's La Poste in euros only."},
  "nationwide": {"theVerdict":"Nationwide Building Society, registered with the FCA and PRA under number 106078, sends money abroad from its current accounts through the internet bank or a branch, as SEPA payments for euros within the SEPA zone and SWIFT payments for everything else. It fits a member paying a foreign bank account, including a large sum, since Nationwide states no limit on what you can send. As of October 2026 it says a third-party provider carries out the currency conversion and that Nationwide receives a share of the mark-up.","measuredRecord":"Nationwide's quotes in our 91-day history are taken at £100. Measured that way it came first on {{LED:nationwide}} comparable corridors, finishing an average {{SHORTFALL:nationwide}} short of the day's top payout. Nationwide's fixed charge on each SWIFT payment bites hardest at £100 and matters less on a large sum, so read that gap as a small-transfer figure and price your real amount in the internet bank.","whereItWins":{"heading":"A large SWIFT payment from a current account","body":"Nationwide sets no ceiling on a SWIFT payment, and a branch will take the instruction if you bring your current account card, a valid passport or full driving licence, and proof of address. Request it in the internet bank instead and the exchange rate is quoted in the online form, so Nationwide says you know exactly how much money will be sent before you commit."},"whereItLoses":{"heading":"Paying from a Nationwide savings account","body":"SWIFT and SEPA payments have to leave from a Nationwide current account; a savings account can be used only when one of its teams advises it, such as after a bereavement. The balance or an overdraft must also cover both the payment and Nationwide's SWIFT transaction fee, or it may refuse the payment, so a transfer that would empty the account to the penny may be turned down."},"watchOut":"Nationwide's <a href=\"https://www.nationwide.co.uk/support/payments-and-transfers/swift-sepa-international-payments\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">SWIFT and SEPA guide</a> says a payment sent in pounds is converted by the receiving foreign bank at its own rate, possibly with its own charges, so the credited amount is outside Nationwide's control. It also wants the recipient's full address down to the postcode or zip code; leave details out and the payment may be rejected, with the money coming back as less than you sent."},
  "westpac": {"theVerdict":"Westpac Banking Corporation (ABN 33 007 457 141, AFSL 233714) is an Australian bank that sends overseas payments from an eligible Westpac transaction account through Online Banking, the Westpac App or a branch, in the currencies its transfer page lists. It suits an account holder aged 14 or over paying a known bank account abroad, including on a schedule, because the app lets you set a date and frequency. Westpac quotes an exact rate that you accept before the payment goes.","measuredRecord":"Westpac appears in our 91-day history on Australian dollar routes at A$100. It was the most frequent winner on {{LED:westpac}} comparable corridors and averaged {{SHORTFALL:westpac}} below the day's leading payout. Two routes need care: as of October 2026 Westpac accepts Philippine peso and Thai baht transfers only from A$1,000, so an A$100 quote there shows its rate rather than a payment it would make.","whereItWins":{"heading":"Scheduled payments and rate targets from Westpac","body":"Setting a date and frequency when you start an overseas payment lets a monthly transfer to the same payee be arranged once. Westpac also offers Fixed FX for locking a rate for a later date, sends alerts for up to 10 target rates per currency pair, and runs a Financial Markets line that it says customers can call to discuss their exchange rate needs."},"whereItLoses":{"heading":"Small sums to Southeast Asia, Pakistan or Mexico","body":"Westpac takes transfers to Cambodia, Ghana, Indonesia, Laos, Mexico, Pakistan, the Philippines, Thailand and Vietnam only from A$1,000 or the foreign currency equivalent, so a modest allowance to those countries needs another route. Rupiah, ringgit, Sri Lankan rupee and Saudi riyal payments run only between 8am Monday and 11:59pm Friday, Sydney time, and personal customers cannot send yuan to China."},"watchOut":"Overseas banks' handling charges fall on the recipient by default, and Westpac's <a href=\"https://www.westpac.com.au/international-travel/international-transfers/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">international transfer page</a> warns that a bank on the route could convert the payment at an unfavourable rate; Westpac suggests the recipient then consider rejecting it so it can be unwound. Personal customers need a Security Device for an international payment of any value, and Westpac says other rates may apply to a future-dated payment than to today's quote."},
  "commonwealth-bank": {"theVerdict":"Commonwealth Bank of Australia (ABN 48 123 123 124, AFSL 234945) sends international money transfers, which it calls IMTs, from a CommBank account through NetBank, the CommBank app or a branch. It suits an Australian customer paying an overseas bank account in that account's own currency: as of October 2026 CommBank says it pays correspondent bank fees on a cross-currency IMT, though not any fee the payee's bank charges.","measuredRecord":"This page publishes no 91-day record for Commonwealth Bank, so nothing here ranks CommBank on cost, though its quotes do appear in our live comparison on Australian dollar routes, ordered by the amount received. For your own payment, compare the amount NetBank or the app shows once you convert to a foreign currency, a step CommBank says locks in the exchange rate.","whereItWins":{"heading":"Tracking an IMT after it leaves NetBank","body":"CommBank's payment tracker in NetBank follows an IMT by its UETR, the 36-character code in your payment details, and the same tool is where you trace, amend or cancel one. Before the money goes, CommBank says its IMT pre-validation feature checks your payment details automatically, a useful guard on a first payment to a new overseas payee."},"whereItLoses":{"heading":"Small transfers arranged in a CommBank branch","body":"A CommBank branch sends an IMT only from AUD 5,000 per transfer, so a customer who cannot use NetBank or the app has no counter route for a small payment. Transfers made at a weekend or on a public or bank holiday wait for the next business day, and a returned payment is converted back at CommBank's published Bank buys IMT rate on the day it is credited, not at the rate you paid."},"watchOut":"CommBank charges for a trace investigation, and its <a href=\"https://www.commbank.com.au/personal/international/international-money-transfer.html\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">IMT page</a> suggests checking the payment tracker first. An IMT the app routes through a payment agent cannot be amended afterwards, only traced or cancelled, and a cancellation is a request that depends on the overseas bank getting authority to return the funds. Check the payee's name, home address and account number before confirming."},
  "lloyds": {"theVerdict":"Lloyds Bank plc (FCA and PRA register number 119278) sends payments abroad from a Lloyds account through its app, online banking, Telephone Banking or a branch counter, and as of April 2026 its help page said payments could be requested day or night, with the money taken once Lloyds processes them. It fits a customer paying an overseas bank account whose currency they already know, since Lloyds lets you send either pounds or the foreign currency and leaves that choice to you.","measuredRecord":"Lloyds sits in our 91-day record on sterling routes at £100, the single amount our history stores. It was the habitual leader on {{LED:lloyds}} comparable corridors and trailed the day's top payout by {{SHORTFALL:lloyds}} on average. A flat per-payment charge weighs heavily on a £100 transfer, so read that gap as a small-payment figure and price your actual amount in the app.","whereItWins":{"heading":"A large sum sent from a Lloyds branch","body":"Lloyds set no maximum on an international payment made in a branch when its help page was captured in April 2026, so a house deposit or a large family gift need not be split across days to fit a digital daily limit. Customers with a Mayfair Private Banking Service account may receive a different standard exchange rate and margin, which Lloyds says to raise with their Private Banking Manager."},"whereItLoses":{"heading":"Comparing quotes before you have set up a payee","body":"Type an amount into Lloyds' payment calculator without choosing or entering a recipient and you get only an illustration; the rate you can continue with appears once a recipient is selected. That makes Lloyds awkward for pricing a transfer in advance against other providers, since a usable quote needs the payee set up first, and the final rate is shown only before you confirm."},"watchOut":"Lloyds' <a href=\"https://www.lloydsbank.com/help-guidance/everyday-banking/payments-and-transfers/send-international-payment.html\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">send money abroad guide</a> explains that most accounts abroad are kept in their local currency, such as Canadian dollar accounts in Canada, so a sterling payment has to be converted by the receiving bank; it suggests pounds where the overseas account is in pounds, you have a special arrangement or you simply prefer it. Ask the recipient which currency their account holds, then use Lloyds' margin calculator for your amount."},
  "anz": {"theVerdict":"Australia and New Zealand Banking Group (ANZ) is an Australian bank that sends international money transfers in more than 30 currencies to over 250 destinations through the ANZ Plus app, ANZ Internet Banking or ANZ Phone Banking. It fits a one-off payment to a bank account abroad, priced on the spot: as of October 2026 ANZ holds the quoted rate for 8 minutes in the Plus app and 10 in Internet Banking, and its quote includes an estimated correspondent fee.","measuredRecord":"ANZ's 91-day record comes from A$100 transfers on Australian dollar routes. It finished as the habitual leader on {{LED:anz}} comparable corridors, and its quote sat {{SHORTFALL:anz}} behind the day's leading payout on average. ANZ sets no minimum transfer, so an A$100 payment is one it will make; at larger amounts its own quote, estimated correspondent fee included, is the number to compare.","whereItWins":{"heading":"A large transfer arranged by phone with ANZ","body":"ANZ Phone Banking has no maximum on an international money transfer from your account, while Internet Banking lets a personal customer set a daily limit of up to $10,000, or $50,000 once the ANZ Shield app is set up. In the Plus app, any daily limit above $30,000 is temporary and ends at 11:59pm on the day you set it, so the phone route suits a one-off large sum."},"whereItLoses":{"heading":"Regular payments, or funding from an ANZ credit card","body":"ANZ does not let you schedule a recurring or future-dated international money transfer, so a monthly payment has to be keyed in each time. Paying from an ANZ credit card is possible only in Internet Banking, where ANZ treats the transfer as a cash advance that earns no ANZ Rewards or Frequent Flyer points, and additional fees, charges and interest may apply."},"watchOut":"ANZ's <a href=\"https://www.anz.com.au/personal/travel-international/international-payments/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">international money transfer page</a> says it does not check the recipient details you enter, so a wrong account number can send the money to the wrong account, and a transfer already passed to the recipient's bank may not be recoverable. Some destinations add steps: ANZ asks for the recipient's passport or citizen card number for Vietnam, and says recipients in South Africa and Bangladesh must contact their bank to claim the funds."},
  "santander": {"theVerdict":"Santander UK plc, on the FCA's Financial Services Register under number 106054, is the UK bank that sends these payments, from a UK current account through Online Banking, Telephone Banking or a branch, but not through its Mobile Banking app. It suits a customer at a computer paying a euro account in the SEPA area, where Santander offers a non-urgent SEPA transfer beside its standard electronic transfer in the 28 currencies its page listed in October 2026.","measuredRecord":"This page carries no 91-day record for Santander and makes no cost claim, though Santander quotes appear in our live comparison on some sterling routes. Its own guide gives a reason to wait for the final figure: it says it will not know the actual exchange rate until the payment completes, so the rate shown at setup can differ from the one on your statement.","whereItWins":{"heading":"Euros to a SEPA account with nothing deducted","body":"When you pay euros into an account in the SEPA area, Santander offers a non-urgent SEPA transfer, and its guide states that deductions cannot be taken from SEPA payments, unlike a SWIFT euro payment to the EEA, which may arrive reduced after a correspondent or the beneficiary's bank deducts a charge. Santander suggests SEPA for that reason, provided the receiving bank accepts SEPA transfers."},"whereItLoses":{"heading":"Sending from your phone, or by currency draft","body":"Santander's international payments run in Online Banking, by phone or in a branch; its Mobile Banking app cannot send them. Since 28 April 2026 it no longer writes cheques in a foreign currency either. And because payments are not processed on non-working days, including holidays in the beneficiary's country, a payment set up before a foreign public holiday can sit unprocessed until the next working day there."},"watchOut":"Outside the EEA, Santander's default is that you pay only the sender's charges and the recipient bears the rest; its <a href=\"https://www.santander.co.uk/personal/support/current-accounts/making-international-payments\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">international payments guide</a> says you can change this under 'Expenses paid by' in Online Banking to cover the beneficiary's charges too, which makes a full amount more likely but not certain. For Mexican peso payments, have the recipient's 18-digit CLABE ready, and expect a one-time passcode when paying a company abroad."},
  "profee": {"theVerdict":"Profee is a trading name of Sibilla Solutions Ltd, a Cyprus company regulated by the Central Bank of Cyprus as an electronic money institution; residents of Canada are served by a separate firm, True Northern Transfers, registered with FINTRAC and licensed in British Columbia. It fits a personal sender supporting family abroad whose recipient receives into a bank account or onto a card, payout methods its user agreement lists, as of October 2026, alongside alternative payment methods.","measuredRecord":"Profee's 91-day record covers euro and sterling routes priced at 100 units of the sending currency, so €100 or £100. It was the usual leader on {{LED:profee}} comparable corridors, and its quote averaged {{SHORTFALL:profee}} behind the day's top payout. Its sterling routes carry far fewer quoted days than the euro ones in that window, so the euro corridors drive most of the average.","whereItWins":{"heading":"Paying a recipient who has no Profee account","body":"Profee says the people you send to do not need to sign up; they only give you their account details. For the sender, the entry level carries an overall limit of EUR 1,000, which rises to an annual EUR 30,000 after proof of identity and to EUR 100,000 at the Plus level with further documents, so regular family support can grow as verification does."},"whereItLoses":{"heading":"Holding money in Profee instead of a bank","body":"A Profee balance is electronic money, not a bank deposit. Its user agreement says the Cyprus deposit compensation scheme does not apply and that money held in the account could be lost if the company became insolvent, though Profee states customer funds sit in segregated safeguarding accounts. The balance earns no interest, and Profee's terms limit accounts to personal use and bar FX speculation or arbitrage."},"watchOut":"Check which company you contract with and what your level allows before a deadline. Profee's <a href=\"https://www.profee.com/documents/user-agreement\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">user agreement</a> names Sibilla Solutions Ltd in Cyprus, with True Northern Transfers serving Canadian residents, and higher limits need the documents each level asks for. Its support team answers by in-app chat, by email or on a Cyprus phone number, on business days from 9:00 to 19:00 (UTC+3), so leave time for a document check."},
  "moneycorp": {"theVerdict":"Moneycorp is the trading name of TTT Moneycorp Limited, which the FCA authorises as a payment institution (firm reference 308919); it calls itself a foreign exchange specialist and is not a bank. Its personal service, as described in October 2026, is built around planned payments such as buying or selling a property abroad, moving pensions or inheritance, and paying tuition, with personal guidance from a dedicated specialist and tools that fix a rate ahead or wait for a target one.","measuredRecord":"Moneycorp has no 91-day lead record here. We collect Moneycorp quotes only for 1,000-unit transfers in the sending currency, while our lead history is built from 100-unit transfers, so it never enters that comparison. Those larger quotes still appear in our live comparison tables; for the sums Moneycorp's service is built around, ask its specialist for a quote at your actual amount.","whereItWins":{"heading":"Fixing a rate for a payment due months away","body":"Moneycorp's forward contract fixes an exchange rate for up to two years, which suits a property completion or a tuition bill with a known date; Moneycorp notes a forward may require a deposit and should be used to pay for goods, services or direct investment. A market order instead waits for a target rate and executes the transfer automatically when the market reaches it."},"whereItLoses":{"heading":"Expecting FSCS cover on money in transit","body":"Money you send Moneycorp to make a payment is safeguarded under the Payment Services Regulations rather than covered by the Financial Services Compensation Scheme, as Moneycorp's safeguarding page explains. If the firm failed, safeguarded funds would come back through the insolvency process, minus the insolvency practitioner's costs. Someone who wants deposit protection while a completion date slips may prefer to keep the money in a bank account until it is due."},"watchOut":"Moneycorp's <a href=\"https://www.moneycorp.com/en-gb/regulatory-information\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">regulatory information</a> names two FCA-authorised companies: TTT Moneycorp Limited for payment services and Moneycorp Financial Risk Management Limited for designated investment business, each with its own reference number. Check which one is named on any contract you sign. The rates shown on Moneycorp's website are indicative, with interbank rates used as a reference, so the rate that counts is the one quoted when you book."},
  "wells-fargo": {"theVerdict":"Wells Fargo Bank, N.A. (Member FDIC, NMLSR ID 399801) is a U.S. bank with two separate ways to pay someone abroad from a Wells Fargo account. Digital Wires, sent from Wells Fargo Online, reach personal and business accounts in the U.S. and 200+ countries, but only for customers with a current U.S. residence. ExpressSend, in the Wells Fargo Mobile app, is a person-to-person service for family in Latin America, the Caribbean and Asia. Both fit an existing customer rather than a newcomer to the bank.","measuredRecord":"Wells Fargo is in our 91-day record on U.S. dollar routes, priced daily at $100. Over that window it led {{LED:wells-fargo}} comparable corridors and averaged {{SHORTFALL:wells-fargo}} below the day's leading payout. Wells Fargo says consumer accounts pay no wire fee on a Digital Wire sent in a foreign currency, which leaves its exchange rate, set at its discretion and including a markup, as the source of that gap.","whereItWins":{"heading":"Cash or a deposit for family in Mexico or Asia","body":"ExpressSend pays either a recipient's eligible bank account or a cash pickup location in Mexico, the Caribbean, Central America, South America and Asia. Wells Fargo's wire guide describes it as a way to send up to $5,000, with limits varying by country, receiving institution and receiving method. You can keep up to 10 recipients on file, and for cash pickup the name you type must exactly match the recipient's government-issued ID."},"whereItLoses":{"heading":"Repeat payments, or sending from a U.S. territory","body":"ExpressSend cannot repeat or future-date a transfer, so each payment is started by hand, and once you accept its mobile terms the service works only in the app, no longer in a web browser, at a branch or by phone. Digital Wires require a current U.S. residence, which shuts out customers living in Puerto Rico, Guam, the U.S. Virgin Islands, American Samoa, the Northern Mariana Islands or another country."},"watchOut":"Wells Fargo's <a href=\"https://www.wellsfargo.com/help/online-banking/wires-faqs/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">Digital Wires FAQs</a> give a 2:20 pm Pacific Time cutoff for international wires; anything later goes the next business day, and an internal security review can hold a wire longer. You can cancel one only while its status reads Scheduled. Wells Fargo also says it adds extra markup to exchange rates outside regular market hours and at weekends, so price a foreign-currency wire on a weekday."},
  "td-bank": {"theVerdict":"TD on this page means The Toronto-Dominion Bank in Canada, whose TD Global Transfer service sends money from the TD app or EasyWeb. Paying from an eligible TD bank account or line of credit, a sender picks one of three payouts: a deposit to a bank account in over 150 countries and territories, a payment to an eligible Visa card through Visa Direct, or cash collected at a Western Union agent. It suits a Canadian customer whose recipient may hold a card but no bank account.","measuredRecord":"TD's 91-day record comes from Canadian dollar routes priced at C$100. It led {{LED:td-bank}} comparable corridors and averaged {{SHORTFALL:td-bank}} behind the day's top payout. TD says it adds no transfer fee of its own to a bank deposit or a Visa Direct payment, so that gap comes from the exchange rate. Western Union cash pickups carry Western Union's own fees and rates, which this record does not price.","whereItWins":{"heading":"A recipient with a Visa card but no usable account","body":"Visa Direct reaches eligible Visa debit, credit and prepaid cards in over 170 countries and territories, and TD asks only for the recipient's 16-digit card number and address, up to $2,500 a day. Western Union cash pickup covers 500,000+ agent locations. Both options sit in the same TD Global Transfer flow as a bank deposit, where you review quotes for the destination before choosing how the money arrives."},"whereItLoses":{"heading":"Large cash pickups, or a transfer you may want back","body":"Cash pickup through Western Union stops at $999.99 a day, $2,999.99 a week and $6,999.99 a month, against $10,000 a day for a bank deposit. A Western Union transfer cannot be cancelled in its first hour or once collected, and returned funds can take up to 5 business days. Bank deposits and Visa Direct payments cannot be cancelled once completed, and TD says youth, government disbursement and travel prepaid cards may be unable to receive Visa Direct."},"watchOut":"TD's <a href=\"https://www.td.com/ca/en/personal-banking/ways-to-bank/ways-to-send/international-money-transfer/td-global-transfer\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">Global Transfer page</a> lists what each country needs: a CLABE for Mexico, the account holder's name plus bank and branch codes for Jamaica, and an account holder number for China. TD warns it may ask for documents outside the app's own steps, and in rare cases the recipient may have to visit a bank to supply them. Regular account transaction fees may also apply to the TD account you send from."},
  "barclays": {"theVerdict":"Barclays Bank UK PLC, on the FCA register under 759676 and authorised since April 2017, sends payments abroad from a Barclays current account in the Barclays app, Online Banking or a branch. Its online country list names 130+ destinations, sorted into groups by the details each one needs, and Barclays says a place missing from that list may still be reachable from a branch. It suits a current account holder paying a bank account in one of the listed countries.","measuredRecord":"Barclays enters our 91-day record through sterling routes priced at £100 each day. Priced that way, it led {{LED:barclays}} comparable corridors and finished {{SHORTFALL:barclays}} behind the day's leading payout on average. Barclays publishes only an upper limit for the conversion charge it adds to its reference rate, not the charge for a given amount, so read the rate the app quotes for your sum before confirming.","whereItWins":{"heading":"Euros to the Channel Islands, Gibraltar or Monaco","body":"Barclays' online list treats Jersey, Guernsey, the Isle of Man, Gibraltar, Monaco, San Marino, Andorra, Vatican City and Switzerland as SEPA destinations, along with EU members and French overseas departments such as Réunion and Martinique. For a payment there, Barclays says it finds out whether the recipient's bank accepts SEPA before you send, so a bank that cannot take a SEPA payment is flagged before the money goes."},"whereItLoses":{"heading":"Paying the UAE or mainland China online","body":"For the United Arab Emirates, Barclays' country page says the charges must be split with the recipient, so the option it offers elsewhere to cover overseas bank charges yourself is missing. For China it wants a detailed purpose of payment and the receiving bank's CNAPS code or SWIFT/BIC, and says the recipient must tell their bank to expect the money. A recipient who needs the exact amount, or cannot warn their bank, is poorly served by either."},"watchOut":"Open your destination on Barclays' <a href=\"https://www.barclays.co.uk/ways-to-bank/international-bank-transfers/send-and-receive-money-online-to-130-plus-countries/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">country list</a> before you send. For places such as Turkey, Kenya, Nigeria, Mexico, Japan and the Philippines it asks for a detailed purpose of payment along with the recipient's address and their bank's address. Barclays' sending guide warns that where a country's banking rules require a reason for the payment, leaving it out can get the payment cancelled, delayed or rejected."},
  "fairfx": {"theVerdict":"FairFX is a trading style of Equals Money UK Limited, which the FCA register lists as an authorised payment institution (reference 504547) since June 2018; it is not a bank. Alongside a prepaid multi-currency Mastercard, it makes international payments online in 40+ currencies, with more available through its in-house currency experts. FairFX pitches the payment service at planned sums such as buying property abroad, funding a child's education or sending money to family, with its currency experts advising on when to buy.","measuredRecord":"FairFX has no 91-day lead record on this page. We collect FairFX quotes only for 1,000-unit pound-to-euro transfers, and the daily history behind lead records uses 100-unit amounts, so FairFX does not enter it. Its quote does appear in our live pound-to-euro comparison; for another currency or a larger planned payment, ask FairFX's currency team to quote your actual amount.","whereItWins":{"heading":"Buying currency now for a payment due later","body":"FairFX says you can buy a currency through its experts when it suits you and hold it in your FairFX account until the payment falls due, with hedging options and rate alerts on offer. Its payments page also describes help with buying, selling and maintaining property abroad, a dedicated currency expert to manage market swings, and live chat from Monday to Friday, 09:00 to 17:00, with email support all year."},"whereItLoses":{"heading":"Topping up from another person's account","body":"FairFX says every payment into an account must come from a bank account in your own name, so a relative cannot fund your balance for you. Balances sit outside the Financial Services Compensation Scheme; instead, FairFX says it keeps customer funds in segregated, safeguarded accounts at Citibank UK, Royal Bank of Scotland or Barclays, apart from its own assets, to repay clients if it became insolvent."},"watchOut":"Check the firm before you send. FairFX's site footer names Equals Money UK Limited with FCA reference 504547, but its FSCS answer quotes FCA number 488396, which the register lists for Equals Money PLC. The <a href=\"https://register.fca.org.uk/s/firm?id=001b000000Mfu1BAAR\" target=\"_blank\" rel=\"noopener noreferrer\">FCA register entry for Equals Money UK Limited</a> shows an authorised payment institution and says FSCS compensation is not available if it fails owing you money. FairFX also notes fees may apply to exotic currencies."},
  "transfergo": {"theVerdict":"TransferGo Ltd is a UK electronic money institution, authorised by the FCA under reference 991295 since January 2024, and a second company, UAB TransferGo Lithuania, holds an e-money licence from the Bank of Lithuania. TransferGo only sends from Europe, and its app pays bank accounts, debit and credit cards and, in some countries, cash. It fits a migrant worker in the UK or EU paying family regularly, and it also offers a multi-currency account and a GoCard.","measuredRecord":"TransferGo appears in our 91-day record on pound routes, priced at £100 each day. It led {{LED:transfergo}} comparable corridors and averaged {{SHORTFALL:transfergo}} behind the day's leading payout. The quotes we hold are for payouts to bank accounts with no separate transfer fee, so the exchange rate accounts for that gap; TransferGo's help pages say card-funded transfers cost more to process than bank transfers.","whereItWins":{"heading":"Paying someone who only gave you a phone number","body":"TransferGo can send to a receiver identified by phone number: it texts them a link, and they have 48 hours to add their bank details before the money is paid out. A card payout needs only the receiver's full name, 16-digit card number and expiry date, up to 2,500 US dollars per transaction, and in Morocco receivers can collect cash with a Cash Plus code and a passport, national ID or driving licence."},"whereItLoses":{"heading":"Sending from outside Europe, or from a shared account","body":"TransferGo says it only supports transfers from Europe, so a sender based in North America, the Gulf or Asia cannot use it. Payment must come from your own personal account: it may ask a joint account holder for a statement showing both names, plus the other holder's date of birth, nationality and ID, and money paid from someone else's account has to be resolved before anything is sent. Users must be 18 or over."},"watchOut":"Pay inside the guaranteed window. TransferGo's <a href=\"https://www.transfergo.com/terms-conditions/transfergo-ltd\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">terms for TransferGo Ltd</a> say a guaranteed rate holds only if your money arrives within the stated period; arrive later and it converts at the rate then applicable, or emails to ask whether to proceed. Its collection accounts are also moving to UAB TransferGo Lithuania, with an Estonian IBAN for euros, so delete old saved payment details and copy the ones the app shows."},
  "hsbc": {"theVerdict":"HSBC UK Bank plc, authorised on the FCA register since July 2017, sends international payments to 150+ destinations from online banking, the HSBC UK app, by phone or in a branch, and from Global Money, an app-only account that sends in 50+ currencies to 200+ countries. It can also link the accounts one customer holds with HSBC in different countries. It fits someone whose money already sits with HSBC in the UK and abroad, or a UK customer paying an overseas bank account.","measuredRecord":"Our HSBC record spans pound routes and Australian dollar routes, with every quote taken at £100 or A$100. Across them HSBC led {{LED:hsbc}} comparable corridors and averaged {{SHORTFALL:hsbc}} behind the day's leading payout. A handful of routes where its quote sat far back pull that average up, while on several others it finished close to the leader, so check your own corridor.","whereItWins":{"heading":"Moving money between your own HSBC accounts abroad","body":"Global View and Global Transfers link HSBC accounts you hold in places including India, the Philippines, Mexico, the UAE, Hong Kong, Singapore and the US, and HSBC UK lets you move up to USD 200,000 a day between them. HSBC says a new overseas account can be linked two days after it is opened, which suits an expatriate keeping one account at home and another where they live."},"whereItLoses":{"heading":"A large payment by phone, or from a basic account","body":"HSBC UK takes up to £50,000 online but only £10,000 by phone unless you bank with Premier, and it says payments made to secure a property or for investment may need extra security checks. Global Money is closed to Basic Bank Account, Appointee and MyAccount holders, who send through standard online banking instead. HSBC UK also no longer processes payments to or from Russia or Belarus."},"watchOut":"Paying someone in the EEA, you cannot choose to cover the other person's charges, HSBC's <a href=\"https://www.hsbc.co.uk/international/money-transfer/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">money transfer page</a> says: you pay HSBC's charge plus any intermediary and agency bank charges, and the receiving bank may take its own from the payment, possibly more than it did before 1 January 2021. Outside the EEA you choose whether to pay all fees, share them or leave them to the beneficiary. Enter the payee's name exactly as their bank holds it."},
  "chase": {"theVerdict":"JPMorgan Chase Bank, N.A. (Member FDIC) sends international wires from Chase checking accounts on chase.com, in the Chase Mobile app or through a banker. Its personal fee schedule, effective 14 June 2026, prices three kinds separately: an online wire abroad in U.S. dollars, an online wire in the recipient's currency, and a wire a banker sends in either. It suits an existing Chase customer paying a foreign bank account, above all when the payment can go in local currency.","measuredRecord":"Chase's 91-day record comes from U.S. dollar routes priced at $100. It led {{LED:chase}} comparable corridors and averaged {{SHORTFALL:chase}} behind the day's top payout. Those quotes include a flat charge, in line with the one Chase's fee schedule sets for an online foreign-currency wire under $5,000, and a flat charge weighs far more on $100 than on a larger wire.","whereItWins":{"heading":"A large online wire in the recipient's currency","body":"Chase's fee schedule waives its own charge on an online foreign-currency wire of $5,000 or more, while an online wire abroad in U.S. dollars and any wire a banker sends carry fixed fees at every size. For a sizeable payment into an account held in local currency, the online foreign-currency wire is therefore the Chase route to price first, leaving the exchange rate as the main cost."},"whereItLoses":{"heading":"Expecting a rate near the one quoted online","body":"Chase's deposit account agreement, effective 14 June 2026, says it sets foreign exchange rates at its sole discretion, with a spread and possibly commissions, and that customers should expect them to be less favorable than rates quoted online or in publications. The rate can also vary with your relationship, the amount, the currency and the date and time of the exchange, so two customers sending the same sum may get different rates."},"watchOut":"Check the account number twice. Chase's <a href=\"https://www.chase.com/content/dam/chase-ux/documents/personal/checking/deposit-account-agreement.pdf\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">deposit account agreement</a> says that if a wire gives an account or bank number and a name that belong to different people, Chase and every other bank handling the transfer may rely on the number alone, with no duty to spot the mismatch. It also says Chase may limit your access to its wire services if you do not use a trusted device."},
  "pnb-europe": {"theVerdict":"PNB Europe is Philippine National Bank (Europe) Plc, a London bank incorporated in 1994 (Companies House 02939223) and authorised under FCA reference 204532; the PNB is Philippine National Bank, not an Indian bank. It sends remittances to the Philippines for Filipinos in the UK and elsewhere in Europe. Its pages, readable to us only in archived copies because the live site refuses automated visits, describe sending over the counter in London, by phone with a debit card, online or by bank transfer.","measuredRecord":"PNB Europe's record covers routes from pounds and euros to Philippine pesos, with each quote taken at £100 or €100. It led {{LED:pnb-europe}} comparable corridors and sat {{SHORTFALL:pnb-europe}} behind the day's top payout on average. Those quotes are for home delivery paid by card and include a per-transfer charge, which bites hardest on a remittance that small.","whereItWins":{"heading":"Door-to-door delivery or a PNB counter in the Philippines","body":"PNB Europe's FAQ says its door-to-door service covers Metro Manila and major cities, and senders can instead name a bank account or the nearest PNB branch for payment over the counter. In London, its Vauxhall Bridge Road office took cash, debit card and credit card remittances on weekdays and from 11:00 to 14:00 at weekends, and its phone service took debit card remittances around the clock, with what it calls bilingual Filipino customer service associates."},"whereItLoses":{"heading":"Signing up from elsewhere in Europe","body":"Outside the UK, PNB Europe's archived pages ask new remitters in countries such as Italy and Denmark to post a registration form to London with one proof of identity and two proofs of address, all certified by their bank manager. Each beneficiary then gets an ID number to quote on bank transfers, and adding a new beneficiary means phoning first for another, a slow start for a one-off payment."},"watchOut":"PNB Europe's <a href=\"https://www.pnb.com.ph/europe/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">remittance page</a>, as archived in November 2025, says its published exchange rates apply to remittances up to £5,000 or €5,000 only; above that, ask staff for the rate before paying. Put the beneficiary's full name, bank name and account number on a bank transfer, as it asks, and check them twice: its FAQ lists an administrative charge for each amendment to a remittance."},
  "rbs": {"theVerdict":"The Royal Bank of Scotland plc, registered in Scotland (SC083026) at 36 St Andrew Square, Edinburgh, and on the FCA register under 114724, sends international payments from an RBS account through the Royal Bank app, Digital Banking or a branch. It is meant for a current customer paying an overseas bank account, including one with a Channel Islands or Isle of Man mobile number, which RBS accepts for its app, which is open to customers from age 11.","measuredRecord":"RBS appears in our 91-day record on sterling routes, priced at £100 a day. It led {{LED:rbs}} comparable corridors and averaged {{SHORTFALL:rbs}} behind the day's leading payout. RBS says it charges no fee to send an international payment online, so for a converted payment the gap sits in its exchange rate margin, which it says can change with the amount you send.","whereItWins":{"heading":"Paying today with the rate fixed on screen","body":"Pay immediately in the app or Digital Banking, before 14:00 UK time for euros or 16:00 for other currencies, and RBS gives a guaranteed exchange rate rather than an estimate. Where the full amount must reach the recipient's bank, RBS offers to charge £10 to cover foreign bank handling fees, shown as a separate statement entry, though it warns intermediary or receiving banks may still take their own charges."},"whereItLoses":{"heading":"Future-dated payments and recalls","body":"A payment dated for later, made after the cut-off or made while the rates system is down gets only an indicative rate, and the rate actually used is set when RBS processes it. Recalling a payment means calling Telephone Banking, and RBS only promises to try; a payment that does come back may lose value in the currency conversion. A scheduled payment can be cancelled until 06:50 UK time on its due date."},"watchOut":"For Canada, RBS's <a href=\"https://www.rbs.co.uk/banking-with-royal-bank-of-scotland/how-to/send-money-abroad.html\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">sending money abroad page</a> warns that Canadian banks usually give customers a 3-figure bank code while a 4-digit one is required, so add a leading zero. It also says US banks generally take only US dollars and will convert a payment sent in pounds; if RBS converts before sending, it shows you its rate and the exact foreign amount. Check the recipient's account currency first."},
};

export function getCompanyEditorial(slug: string): CompanyEditorial | undefined {
  return companyEditorial[slug];
}
